async function readWrapped(path){const response=await fetch(path);if(!response.ok)throw Error('Map chunk unavailable');const stream=response.body.pipeThrough(new DecompressionStream('gzip'));const source=await new Response(stream).text();const comma=source.indexOf(',');return JSON.parse(source.slice(comma+1,source.lastIndexOf(')')))}
