function popup(p){return '<b>Habitat polygon</b><br>'+esc(p.layer)+' / '+esc(p.id)+'<p><b>Candidate species</b><br>'+esc(p.species).replaceAll('|','<br>')+'</p><p><b>Evidence tier:</b> '+esc(p.tier)+'<br><b>Geometry:</b> '+esc(p.basis)+'</p><p><b>Compatible model candidates:</b><br>'+esc(p.models||'None listed').replaceAll('|','<br>')+'</p><div id="polygon-links">Loading linked FORA cells…</div><p>Species candidates are provisional.</p>'}
