async function forcingGroup(v,c){let key=v+'/'+Math.floor(c[2])+'_'+Math.floor(c[3]);if(!forcingCache.has(key)){let promise=(async()=>{let response=await fetch(dataRoot+'forcing/'+key+'.bin.gz');if(!response.ok)throw Error('Daily series is not available for this cell.');let buf=await new Response(response.body.pipeThrough(new DecompressionStream('gzip'))).arrayBuffer(),n=new DataView(buf).getUint32(0,true),header=JSON.parse(new TextDecoder().decode(new Uint8Array(buf,4,n)));return {header,buf,offset:4+n}})();forcingCache.set(key,promise)}return forcingCache.get(key)}
