by('closeForcing').onclick=()=>by('forcingDialog').close();by('forcingCsv').onclick=()=>{if(!currentForcing.length)return;let csv='date,'+currentForcing.map(t=>'"'+t.name+' ('+t.unit+')"').join(',')+'\n'+currentForcing[0].x.map((d,i)=>d+','+currentForcing.map(t=>t.y[i]??'').join(',')).join('\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='fora_daily.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};

